import { useState, useRef, useEffect } from 'react'
import { GearCategory, WeightUnit } from '@/types/database'
import { convertToGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { captureError } from '@/lib/sentry'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { ChevronDown, ChevronUp, Plus, X } from 'lucide-react'

interface AddGearFormProps {
  onAdd: (gear: {
    name: string
    weight_grams: number
    category: string
    quantity: number
    worn: boolean
    consumable: boolean
    notes?: string | null
    price?: number | null
    description?: string | null
    image_url?: string | null
    brand?: string | null
  }) => void
  onCancel?: () => void
  simplified?: boolean // For trip flow
}

const categories: GearCategory[] = [
  'Shelter',
  'Sleep System',
  'Cooking',
  'Water',
  'Clothing',
  'Electronics',
  'First Aid',
  'Navigation',
  'Other'
]

// Smart category suggestions based on item name
const categorySuggestions: Record<string, GearCategory> = {
  tent: 'Shelter',
  tarp: 'Shelter',
  hammock: 'Shelter',
  footprint: 'Shelter',
  'sleeping bag': 'Sleep System',
  quilt: 'Sleep System',
  pad: 'Sleep System',
  pillow: 'Sleep System',
  stove: 'Cooking',
  pot: 'Cooking',
  spoon: 'Cooking',
  fuel: 'Cooking',
  filter: 'Water',
  bottle: 'Water',
  bladder: 'Water',
  purification: 'Water',
  jacket: 'Clothing',
  pants: 'Clothing',
  shirt: 'Clothing',
  socks: 'Clothing',
  phone: 'Electronics',
  battery: 'Electronics',
  charger: 'Electronics',
  headlamp: 'Electronics',
  'first aid': 'First Aid',
  bandage: 'First Aid',
  medication: 'First Aid',
  map: 'Navigation',
  compass: 'Navigation',
  gps: 'Navigation'
}

export function AddGearForm({ onAdd, onCancel, simplified = false }: AddGearFormProps) {
  // Core fields
  const [name, setName] = useState('')
  const [brand, setBrand] = useState('')
  const [weightValue, setWeightValue] = useState('')
  const [weightUnit, setWeightUnit] = useState<WeightUnit>('oz')
  const [category, setCategory] = useState<GearCategory>('Other')
  const [quantity, setQuantity] = useState(1)

  // Advanced fields
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [worn, setWorn] = useState(false)
  const [consumable, setConsumable] = useState(false)
  const [price, setPrice] = useState('')
  const [description, setDescription] = useState('')
  const [imageUrl, setImageUrl] = useState('')
  const [notes, setNotes] = useState('')

  // UI state
  const [weightError, setWeightError] = useState('')
  const nameInputRef = useRef<HTMLInputElement>(null)

  // Auto-focus on mount (mobile-friendly)
  useEffect(() => {
    if (nameInputRef.current) {
      nameInputRef.current.focus()
    }
  }, [])

  // Smart category suggestion
  useEffect(() => {
    if (name) {
      const lowerName = name.toLowerCase()
      for (const [keyword, suggestedCategory] of Object.entries(categorySuggestions)) {
        if (lowerName.includes(keyword)) {
          setCategory(suggestedCategory)
          break
        }
      }
    }
  }, [name])

  // Parse weight input for smart entry (e.g., "12 oz", "340g")
  const handleWeightBlur = () => {
    const parsed = parseWeightInput(weightValue)
    if (parsed) {
      setWeightValue(parsed.value.toString())
      setWeightUnit(parsed.unit)
      setWeightError('')
    }
  }

  // Calculate weight in grams for display
  const getWeightInGrams = (): number => {
    const value = parseFloat(weightValue)
    if (isNaN(value)) return 0
    return Math.round(convertToGrams(value, weightUnit))
  }

  // Format weight preview in multiple units
  const getWeightPreview = (): string => {
    const grams = getWeightInGrams()
    if (grams === 0) return ''

    const units: WeightUnit[] = ['g', 'oz', 'lb', 'kg']
    const previews = units
      .filter(u => u !== weightUnit)
      .map(u => formatWeightWithUnit(grams, u))

    return `(${previews.join(' / ')})`
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    try {
      // Validate required fields
      if (!name.trim()) {
        nameInputRef.current?.focus()
        return
      }

      const weightNum = parseFloat(weightValue)
      if (isNaN(weightNum) || weightNum <= 0) {
        setWeightError('Please enter a valid weight')
        return
      }

      const weightGrams = getWeightInGrams()

      onAdd({
        name: name.trim(),
        brand: brand.trim() || null,
        weight_grams: weightGrams,
        category,
        quantity,
        worn,
        consumable,
        price: price ? parseFloat(price) : null,
        description: description.trim() || null,
        image_url: imageUrl.trim() || null,
        notes: notes.trim() || null
      })

      // Reset form
      setName('')
      setBrand('')
      setWeightValue('')
      setCategory('Other')
      setQuantity(1)
      setWorn(false)
      setConsumable(false)
      setPrice('')
      setDescription('')
      setImageUrl('')
      setNotes('')
      setShowAdvanced(false)

      // Re-focus for quick entry
      nameInputRef.current?.focus()

    } catch (error) {
      captureError(error as Error, {
        component: 'AddGearForm',
        action: 'handleSubmit',
        formData: { 
          name, 
          brand, 
          weightValue, 
          weightUnit, 
          category, 
          quantity, 
          worn, 
          consumable, 
          price, 
          description, 
          imageUrl, 
          notes 
        }
      })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Cmd/Ctrl + Enter to submit
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSubmit(e)
    }
  }

  return (
    <form 
      onSubmit={handleSubmit}
      onKeyDown={handleKeyDown}
      className="bg-white rounded-lg shadow-sm border p-4 md:p-6"
    >
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-lg font-semibold">Add Gear</h2>
        {onCancel && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onCancel}
            className="md:hidden"
          >
            <X className="h-4 w-4" />
          </Button>
        )}
      </div>

      {/* Core Fields - Always Visible */}
      <div className="space-y-4">
        {/* Name and Brand Row */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <div className="md:col-span-2">
            <Label htmlFor="name" className="text-sm">
              Item Name *
            </Label>
            <Input
              ref={nameInputRef}
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., Ultralight tent"
              required
              className="mt-1"
              autoComplete="off"
            />
          </div>
          <div>
            <Label htmlFor="brand" className="text-sm">
              Brand
            </Label>
            <Input
              id="brand"
              type="text"
              value={brand}
              onChange={(e) => setBrand(e.target.value)}
              placeholder="e.g., Zpacks"
              className="mt-1"
            />
          </div>
        </div>

        {/* Weight Input with Unit Selector */}
        <div>
          <Label htmlFor="weight" className="text-sm">
            Weight * {getWeightPreview() && (
              <span className="text-gray-500 font-normal ml-2">{getWeightPreview()}</span>
            )}
          </Label>
          <div className="flex gap-2 mt-1">
            <Input
              id="weight"
              type="number"
              step="0.1"
              value={weightValue}
              onChange={(e) => {
                setWeightValue(e.target.value)
                setWeightError('')
              }}
              onBlur={handleWeightBlur}
              placeholder="Enter weight"
              required
              className={`flex-1 ${weightError ? 'border-red-500' : ''}`}
              inputMode="decimal"
            />
            <select
              value={weightUnit}
              onChange={(e) => setWeightUnit(e.target.value as WeightUnit)}
              className="px-3 py-2 border rounded-md bg-white min-w-[80px]"
            >
              <option value="g">grams</option>
              <option value="oz">ounces</option>
              <option value="lb">pounds</option>
              <option value="kg">kilograms</option>
            </select>
          </div>
          {weightError && (
            <p className="text-red-500 text-sm mt-1">{weightError}</p>
          )}
        </div>

        {/* Category and Quantity */}
        <div className="grid grid-cols-2 gap-3">
          <div>
            <Label htmlFor="category" className="text-sm">
              Category
            </Label>
            <select
              id="category"
              value={category}
              onChange={(e) => setCategory(e.target.value as GearCategory)}
              className="w-full px-3 py-2 border rounded-md bg-white mt-1"
            >
              {categories.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
          <div>
            <Label htmlFor="quantity" className="text-sm">
              Quantity
            </Label>
            <Input
              id="quantity"
              type="number"
              value={quantity}
              onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
              min="1"
              className="mt-1"
              inputMode="numeric"
            />
          </div>
        </div>

        {/* Advanced Fields Toggle */}
        {!simplified && (
          <button
            type="button"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAdvanced ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
            {showAdvanced ? 'Hide' : 'Show'} advanced options
          </button>
        )}

        {/* Advanced Fields */}
        {showAdvanced && !simplified && (
          <div className="space-y-4 pt-2 border-t">
            {/* Checkboxes */}
            <div className="flex gap-6">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={worn}
                  onChange={(e) => setWorn(e.target.checked)}
                  className="rounded"
                />
                <span className="text-sm">Worn weight</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={consumable}
                  onChange={(e) => setConsumable(e.target.checked)}
                  className="rounded"
                />
                <span className="text-sm">Consumable</span>
              </label>
            </div>

            {/* Price */}
            <div>
              <Label htmlFor="price" className="text-sm">
                Price (USD)
              </Label>
              <Input
                id="price"
                type="number"
                step="0.01"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                placeholder="0.00"
                className="mt-1"
                inputMode="decimal"
              />
            </div>

            {/* Description */}
            <div>
              <Label htmlFor="description" className="text-sm">
                Description
              </Label>
              <textarea
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="w-full px-3 py-2 border rounded-md mt-1 resize-none"
                rows={2}
                placeholder="Brief description of the item"
              />
            </div>

            {/* Image URL */}
            <div>
              <Label htmlFor="imageUrl" className="text-sm">
                Image or Product URL
              </Label>
              <Input
                id="imageUrl"
                type="url"
                value={imageUrl}
                onChange={(e) => setImageUrl(e.target.value)}
                placeholder="https://..."
                className="mt-1"
              />
            </div>

            {/* Notes */}
            <div>
              <Label htmlFor="notes" className="text-sm">
                Notes
              </Label>
              <textarea
                id="notes"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="w-full px-3 py-2 border rounded-md mt-1 resize-none"
                rows={2}
                placeholder="Additional notes or reminders"
              />
            </div>
          </div>
        )}
      </div>

      {/* Action Buttons */}
      <div className="flex gap-2 mt-6">
        <Button type="submit" className="flex-1 md:flex-initial">
          <Plus className="h-4 w-4 mr-2" />
          {simplified ? 'Add & Continue' : 'Add Gear'}
        </Button>
        {onCancel && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            className="hidden md:inline-flex"
          >
            Cancel
          </Button>
        )}
      </div>

      {/* Keyboard hint */}
      <p className="text-xs text-gray-500 mt-2 hidden md:block">
        Tip: Press Cmd+Enter to quickly add item
      </p>
    </form>
  )
}

