        action: 'handleSubmit',
        formData: { 
          name, 
          brand, 
          weightValue, 
          weightUnit, 
          category, 
          quantity, 
          worn, 
          consumable, 
          price, 
          description, 
          imageUrl, 
          notes 
        }
      })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Cmd/Ctrl + Enter to submit
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSubmit(e)
    }
  }

  return (
    <form 
      onSubmit={handleSubmit}
      onKeyDown={handleKeyDown}
      className="bg-white rounded-lg shadow-sm border p-4 md:p-6"
    >
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-lg font-semibold">Add Gear</h2>
        {onCancel && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onCancel}
            className="md:hidden"
          >
            <X className="h-4 w-4" />
          </Button>
        )}
      </div>

      {/* Core Fields - Always Visible */}
      <div className="space-y-3">
        {/* Name and Brand Row */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-3">
          <div className="md:col-span-3">
            <Label htmlFor="name" className="text-sm">
              Item Name *
            </Label>
            <Input
              ref={nameInputRef}
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., Ultralight tent"
              required
              className="mt-1"
              autoComplete="off"
            />
          </div>
          <div className="md:col-span-2">
            <Label htmlFor="brand" className="text-sm">
              Brand
            </Label>
            <Input
              id="brand"
              type="text"
              value={brand}
              onChange={(e) => setBrand(e.target.value)}
              placeholder="e.g., Zpacks"
              className="mt-1"
            />
          </div>
        </div>

        {/* Weight, Category, and Quantity Row */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-3">
          {/* Weight Input with Unit Selector */}
          <div className="md:col-span-2">
            <Label htmlFor="weight" className="text-sm">
              Weight * {getWeightPreview() && (
                <span className="text-gray-500 font-normal ml-1 text-xs">{getWeightPreview()}</span>
              )}
            </Label>
            <div className="flex gap-1 mt-1">
              <Input
                id="weight"
                type="number"
                step="0.1"
                value={weightValue}
                onChange={(e) => {
                  setWeightValue(e.target.value)
                  setWeightError('')
                }}
                onBlur={handleWeightBlur}
                placeholder="Weight"
                required
                className={`flex-1 ${weightError ? 'border-red-500' : ''}`}
                inputMode="decimal"
              />
              <select
                value={weightUnit}
                onChange={(e) => setWeightUnit(e.target.value as WeightUnit)}
                className="px-2 py-2 border rounded-md bg-white min-w-[60px] text-sm"
              >
                <option value="g">g</option>
                <option value="oz">oz</option>
                <option value="lb">lb</option>
                <option value="kg">kg</option>
              </select>
            </div>
            {weightError && (
              <p className="text-red-500 text-sm mt-1">{weightError}</p>
            )}
          </div>

          {/* Category */}
          <div className="md:col-span-2">
            <Label htmlFor="category" className="text-sm">
              Category
            </Label>
            <select
              id="category"
              value={category}
              onChange={(e) => setCategory(e.target.value as GearCategory)}
              className="w-full px-3 py-2 border rounded-md bg-white mt-1"
            >
              {categories.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>

          {/* Quantity */}
          <div className="md:col-span-1">
            <Label htmlFor="quantity" className="text-sm">
              Qty
            </Label>
            <Input
              id="quantity"
              type="number"
              value={quantity}
              onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
              min="1"
              className="mt-1"
              inputMode="numeric"
            />
          </div>
        </div>

        {/* Advanced Fields Toggle */}
        {!simplified && (
          <button
            type="button"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAdvanced ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
            {showAdvanced ? 'Hide' : 'Show'} advanced options
          </button>
        )}

        {/* Advanced Fields */}
        {showAdvanced && !simplified && (
          <div className="space-y-3 pt-2 border-t">
            {/* Checkboxes and Price Row */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 items-end">
              <div className="flex gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={worn}
                    onChange={(e) => setWorn(e.target.checked)}
                    className="rounded"
                  />
                  <span className="text-sm">Worn</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={consumable}
                    onChange={(e) => setConsumable(e.target.checked)}
                    className="rounded"
                  />
                  <span className="text-sm">Consumable</span>
                </label>
              </div>

              <div>
                <Label htmlFor="price" className="text-sm">
                  Price (USD)
                </Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  className="mt-1"
                  inputMode="decimal"
                />
              </div>

              <div>
                <Label htmlFor="imageUrl" className="text-sm">
                  Product URL
                </Label>
                <Input
                  id="imageUrl"
                  type="url"
                  value={imageUrl}
                  onChange={(e) => setImageUrl(e.target.value)}
                  placeholder="https://..."
                  className="mt-1"
                />
              </div>
            </div>

            {/* Description and Notes Row */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div>
                <Label htmlFor="description" className="text-sm">
                  Description
                </Label>
                <textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md mt-1 resize-none"
                  rows={2}
                  placeholder="Brief description"
                />
              </div>

              <div>
                <Label htmlFor="notes" className="text-sm">
                  Notes
                </Label>
                <textarea
                  id="notes"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md mt-1 resize-none"
                  rows={2}
                  placeholder="Additional notes"
                />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Action Buttons */}
      <div className="flex gap-2 mt-6">
        <Button type="submit" className="flex-1 md:flex-initial">
          <Plus className="h-4 w-4 mr-2" />
          {simplified ? 'Add & Continue' : 'Add Gear'}
        </Button>
        {onCancel && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            className="hidden md:inline-flex"
          >
            Cancel
          </Button>
        )}
      </div>

      {/* Keyboard hint */}
      <p className="text-xs text-gray-500 mt-2 hidden md:block">
        Tip: Press Cmd+Enter to quickly add item
      </p>
    </form>
  )
}

