import { test, expect } from '@playwright/test'

// E2E tests focus on user journeys and critical paths
// They test the full stack integration without mocking

test.describe('Gear Management', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the app
    await page.goto('/')

    // For now, we'll test the unauthenticated state
    // TODO: Add authentication flow when auth is implemented
  })

  test('should display the gear management interface', async ({ page }) => {
    // Check that the main interface elements are present
    await expect(page.getByText('BetterPack')).toBeVisible()

    // Check for gear-related navigation or buttons
    await expect(page.getByRole('button')).toBeVisible()
  })

  test('should allow adding new gear items', async ({ page }) => {
    // This test assumes the add gear form is accessible
    // We'll skip auth for now and test the core functionality

    // Look for add gear button or form
    const addButton = page.getByRole('button', { name: /add/i }).first()
    if (await addButton.isVisible()) {
      await addButton.click()
    }

    // Fill out the form if it's visible
    const nameInput = page.getByLabel(/name/i)
    if (await nameInput.isVisible()) {
      await nameInput.fill('Test Tent')

      const weightInput = page.getByLabel(/weight/i)
      await weightInput.fill('2.5')

      // Submit the form
      await page.getByRole('button', { name: /add gear/i }).click()

      // Verify the item was added (this will depend on the UI implementation)
      await expect(page.getByText('Test Tent')).toBeVisible()
    }
  })

  test('should be responsive on mobile', async ({ page }) => {
    // Test mobile viewport
    await page.setViewportSize({ width: 375, height: 667 })

    // Check that the interface adapts to mobile
    await expect(page.getByRole('main')).toBeVisible()

    // Verify touch-friendly interface elements
    const buttons = page.getByRole('button')
    const buttonCount = await buttons.count()

    for (let i = 0; i < Math.min(buttonCount, 3); i++) {
      const button = buttons.nth(i)
      if (await button.isVisible()) {
        const box = await button.boundingBox()
        if (box) {
          // Check minimum touch target size (44x44px)
          expect(box.width).toBeGreaterThanOrEqual(40)
          expect(box.height).toBeGreaterThanOrEqual(40)
        }
      }
    }
  })
})

test.describe('Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/')
  })

  test('should validate required fields', async ({ page }) => {
    // Try to find and interact with the gear form
    const addButton = page.getByRole('button', { name: /add/i }).first()
    if (await addButton.isVisible()) {
      await addButton.click()
    }

    // Try to submit without filling required fields
    const submitButton = page.getByRole('button', { name: /add gear/i })
    if (await submitButton.isVisible()) {
      await submitButton.click()

      // Should still be on the form (not submitted)
      await expect(submitButton).toBeVisible()
    }
  })

  test('should handle weight unit conversion', async ({ page }) => {
    const addButton = page.getByRole('button', { name: /add/i }).first()
