import { WeightUnit } from '@/types/database'

export function gramsToKilograms(grams: number): number {
  return grams / 1000
}

export function gramsToPounds(grams: number): number {
  return grams / 453.592
}

export function gramsToOunces(grams: number): number {
  return grams / 28.3495
}

export function kilogramsToGrams(kg: number): number {
  return kg * 1000
}

export function poundsToGrams(lbs: number): number {
  return lbs * 453.592
}

export function ouncesToGrams(oz: number): number {
  return oz * 28.3495
}

export function convertToGrams(value: number, unit: WeightUnit): number {
  switch (unit) {
    case 'kg':
      return kilogramsToGrams(value)
    case 'lb':
      return poundsToGrams(value)
    case 'oz':
      return ouncesToGrams(value)
    case 'g':
    default:
      return value
  }
}

export function convertFromGrams(grams: number, unit: WeightUnit): number {
  switch (unit) {
    case 'kg':
      return gramsToKilograms(grams)
    case 'lb':
      return gramsToPounds(grams)
    case 'oz':
      return gramsToOunces(grams)
    case 'g':
    default:
      return grams
  }
}

export function formatWeight(grams: number, unit: 'g' | 'kg' | 'lb' | 'oz' = 'g'): string {
  switch (unit) {
    case 'kg':
      return `${gramsToKilograms(grams).toFixed(2)}kg`
    case 'lb':
      return `${gramsToPounds(grams).toFixed(2)}lb`
    case 'oz':
      return `${gramsToOunces(grams).toFixed(1)}oz`
    default:
      return `${grams}g`
  }
}

export function calculateTotalWeight(items: { weight_grams: number; quantity: number }[]): number {
  return items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
}

export function parseWeightInput(input: string): { value: number; unit: WeightUnit } | null {
  const trimmed = input.trim().toLowerCase()

  // Match patterns like "12.5 oz", "340g", "1.2kg", "2 lbs"
  const match = trimmed.match(/^([\d.]+)\s*(g|grams?|oz|ounces?|kg|kilograms?|lbs?|pounds?)$/i)

  if (!match) return null

  const value = parseFloat(match[1])
  if (isNaN(value)) return null

  const unitStr = match[2].toLowerCase()
  let unit: WeightUnit = 'g'

  if (unitStr.startsWith('kg') || unitStr === 'kilograms') {
    unit = 'kg'
  } else if (unitStr.startsWith('lb') || unitStr.startsWith('pound')) {
    unit = 'lb'
  } else if (unitStr.startsWith('oz') || unitStr.startsWith('ounce')) {
    unit = 'oz'
  } else {
    unit = 'g'
  }

  return { value, unit }
}

export function getSmartUnit(grams: number): WeightUnit {
  // Suggest the most readable unit based on the weight
  if (grams >= 1000) {
    return 'kg'
  } else if (grams >= 450) {
    return 'lb'
  } else if (grams >= 100) {
    return 'oz'
  } else {
    return 'g'
  }
}

export function formatWeightWithUnit(grams: number, preferredUnit?: WeightUnit): string {
  const unit = preferredUnit || getSmartUnit(grams)
  const value = convertFromGrams(grams, unit)

  // Format with appropriate decimal places
  let formatted: string
  switch (unit) {
    case 'kg':
      formatted = value.toFixed(2)
      break
    case 'lb':
      formatted = value.toFixed(2)
      break
    case 'oz':
      formatted = value.toFixed(1)
      break
    default:
      formatted = Math.round(value).toString()
  }

  return `${formatted}${unit}`
}

