} from './weight'

describe('Weight Utils', () => {
  describe('convertToGrams', () => {
    it('converts ounces to grams correctly', () => {
      expect(convertToGrams(1, 'oz')).toBeCloseTo(28.35, 1)
      expect(convertToGrams(2.5, 'oz')).toBeCloseTo(70.87, 1)
    })

    it('converts pounds to grams correctly', () => {
      expect(convertToGrams(1, 'lb')).toBeCloseTo(453.59, 1)
      expect(convertToGrams(0.5, 'lb')).toBeCloseTo(226.8, 1)
    })

    it('converts kilograms to grams correctly', () => {
      expect(convertToGrams(1, 'kg')).toBe(1000)
      expect(convertToGrams(0.25, 'kg')).toBe(250)
    })

    it('returns grams unchanged', () => {
      expect(convertToGrams(100, 'g')).toBe(100)
      expect(convertToGrams(50.5, 'g')).toBe(50.5)
    })
  })

  describe('convertFromGrams', () => {
    it('converts grams to ounces correctly', () => {
      expect(convertFromGrams(28.35, 'oz')).toBeCloseTo(1, 2)
      expect(convertFromGrams(100, 'oz')).toBeCloseTo(3.53, 2)
    })

    it('converts grams to pounds correctly', () => {
      expect(convertFromGrams(453.59, 'lb')).toBeCloseTo(1, 2)
      expect(convertFromGrams(1000, 'lb')).toBeCloseTo(2.2, 1)
    })
  })

  describe('formatWeightWithUnit', () => {
    it('formats weight with appropriate precision', () => {
      expect(formatWeightWithUnit(100, 'g')).toBe('100g')
      expect(formatWeightWithUnit(1000, 'kg')).toBe('1kg')
      expect(formatWeightWithUnit(453.59, 'lb')).toBe('1lb')
      expect(formatWeightWithUnit(28.35, 'oz')).toBe('1oz')
    })

    it('handles decimal values properly', () => {
      expect(formatWeightWithUnit(150.5, 'g')).toBe('150.5g')
      expect(formatWeightWithUnit(42.5, 'oz')).toBe('1.5oz')
    })
  })

  describe('parseWeightInput', () => {
    it('parses weight input with units', () => {
      expect(parseWeightInput('10 oz')).toEqual({ value: 10, unit: 'oz' })
      expect(parseWeightInput('2.5lb')).toEqual({ value: 2.5, unit: 'lb' })
      expect(parseWeightInput('500g')).toEqual({ value: 500, unit: 'g' })
      expect(parseWeightInput('1.2 kg')).toEqual({ value: 1.2, unit: 'kg' })
    })

    it('handles input without units', () => {
      expect(parseWeightInput('100')).toEqual({ value: 100, unit: 'g' })
    })

    it('handles invalid input', () => {
      expect(parseWeightInput('')).toBeNull()
      expect(parseWeightInput('invalid')).toBeNull()
      expect(parseWeightInput('abc oz')).toBeNull()
    })

    it('handles various spacing and formats', () => {
      expect(parseWeightInput(' 10 oz ')).toEqual({ value: 10, unit: 'oz' })
      expect(parseWeightInput('10OZ')).toEqual({ value: 10, unit: 'oz' })
      expect(parseWeightInput('10 ounces')).toEqual({ value: 10, unit: 'oz' })
    })
  })
})

