    const weight_grams = parseWeightFromText(weightText)
    if (weight_grams <= 0) return null

    return {
      name,
      weight_grams,
      category: 'Other', // Would need to be extracted from context
      quantity: 1,
      worn: false,
      consumable: false
    }
  } catch {
    return null
  }
}

/**
 * Map emoji categories to our category names
 */
function mapEmojiToCategory(emojiCategory: string): string | null {
  for (const [emoji, category] of Object.entries(CATEGORY_MAPPINGS)) {
    if (emojiCategory.includes(emoji)) {
      return category
    }
  }
  return null
}

/**
 * Parse weight from text (handles various formats)
 */
function parseWeightFromText(text: string): number {
  const cleaned = text.toLowerCase().replace(/[^\d.,oz\s]/g, '').trim()

  const numberMatch = cleaned.match(/([\d.,]+)/)
  if (!numberMatch) return 0

  const value = parseFloat(numberMatch[1].replace(',', ''))
  if (isNaN(value)) return 0

  // Check unit
  if (cleaned.includes('oz')) {
    return Math.round(value * 28.3495) // Convert oz to grams
  }

  return Math.round(value) // Assume grams
}

