import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Upload, Link, CheckCircle, AlertCircle, Info } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportResults } from './ImportResults'
import type { ParsedGearItem } from '@/utils/csvParser'

interface ImportGearFormProps {
  onImportComplete: (items: ParsedGearItem[]) => Promise<void>
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview' | 'importing' | 'complete'
  items: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

export function ImportGearForm({ onImportComplete, onCancel, className }: ImportGearFormProps) {
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('csv')
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    errors: [],
    warnings: []
  })

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    setImportState({
      step: data.length > 0 ? 'preview' : 'input',
      items: data,
      errors,
      warnings,
      metadata
    })
  }

  const handleConfirmImport = async () => {
    setImportState(prev => ({ ...prev, step: 'importing' }))

    try {
      await onImportComplete(importState.items)
      setImportState(prev => ({ ...prev, step: 'complete' }))
    } catch (error) {
      setImportState(prev => ({
        ...prev,
        step: 'preview',
        errors: [...prev.errors, `Import failed: ${error instanceof Error ? error.message : 'Unknown error'}`]
      }))
    }
  }

  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      errors: [],
      warnings: []
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <Card className={className}>
        <CardHeader>
          <CardTitle className=\"flex items-center gap-2\">
            <CheckCircle className=\"h-5 w-5 text-green-600\" />
            Import Preview
          </CardTitle>
          <CardDescription>
            Review your gear items before importing
            {importState.metadata?.listName && (
              <span className=\"block font-medium mt-1\">{importState.metadata.listName}</span>
            )}
          </CardDescription>
        </CardHeader>
        <CardContent className=\"space-y-4\">
          {/* Errors */}
          {importState.errors.length > 0 && (
            <Alert variant=\"destructive\">
              <AlertCircle className=\"h-4 w-4\" />
              <AlertDescription>
                <div className=\"font-medium mb-2\">Import Errors:</div>
                <ul className=\"list-disc list-inside space-y-1\">
                  {importState.errors.map((error, i) => (
                    <li key={i} className=\"text-sm\">{error}</li>
                  ))}
                </ul>
              </AlertDescription>
            </Alert>
          )}

          {/* Warnings */}
          {importState.warnings.length > 0 && (
            <Alert>
              <Info className=\"h-4 w-4\" />
              <AlertDescription>
