      expect(result.data[0].weight_grams).toBeCloseTo(71, 0) // 2.5oz ≈ 71g
      expect(result.data[1].weight_grams).toBe(1200)
      expect(result.data[2].weight_grams).toBeCloseTo(43, 0) // 1.5oz ≈ 43g
    })

    it('should handle quoted fields with commas', () => {
      const csv = `name,weight,description
"Tent, 2-person",1200g,"Lightweight, waterproof"
Stove,150g,"Compact, efficient"`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].name).toBe('Tent, 2-person')
      expect(result.data[0].description).toBe('Lightweight, waterproof')
    })

    it('should handle flexible column naming', () => {
      const csv = `Item Name,Weight (g),Gear Type,Qty,Brand
Ultralight Tent,1000,Shelter,1,Zpacks
Water Bottle,100,Water,2,Nalgene`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.data[0]).toMatchObject({
        name: 'Ultralight Tent',
        weight_grams: 1000,
        category: 'Shelter',
        quantity: 1,
        brand: 'Zpacks'
      })
    })

    it('should handle boolean fields', () => {
      const csv = `name,weight,worn,consumable
Base Layer,200g,true,false
Energy Bar,50g,no,yes`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].worn).toBe(true)
      expect(result.data[0].consumable).toBe(false)
      expect(result.data[1].worn).toBe(false)
      expect(result.data[1].consumable).toBe(true)
    })

    it('should handle price parsing', () => {
      const csv = `name,weight,price
Tent,1200g,$299.99
Stove,150g,89.50`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].price).toBe(299.99)
      expect(result.data[1].price).toBe(89.50)
    })

    it('should fail with missing required columns', () => {
      const csv = `description,color
Nice tent,Blue`

      const result = parseCsv(csv)

      expect(result.success).toBe(false)
      expect(result.errors).toContain('No name/item column found. Required columns: name, weight')
    })

    it('should handle empty rows and malformed data gracefully', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter

,invalid,
Good Item,500g,Other`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2) // Should skip empty/invalid rows
      expect(result.data[0].name).toBe('Tent')
      expect(result.data[1].name).toBe('Good Item')
    })

    it('should provide detailed error messages for invalid rows', () => {
      const csv = `name,weight
,200g
ValidItem,invalid_weight`

      const result = parseCsv(csv)

      expect(result.errors.length).toBeGreaterThan(0)
      expect(result.errors.some(e => e.includes('Item name is required'))).toBe(true)
    })
  })

  describe('validateGearItems', () => {
    it('should validate correct items', () => {
      const items = [
        {
          name: 'Tent',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Water Bottle',
          weight_grams: 150,
          category: 'Water',
          quantity: 2,
          worn: false,
          consumable: false,
          price: 25.99
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(2)
      expect(result.invalid).toHaveLength(0)
    })

    it('should catch validation errors', () => {
      const items = [
        {
          name: 'A', // Too short
          weight_grams: 0, // Invalid weight
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Heavy Item',
          weight_grams: 100000, // Too heavy
          category: 'Other',
          quantity: 0, // Invalid quantity
          worn: false,
          consumable: false,
          price: -10 // Negative price
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(0)
      expect(result.invalid).toHaveLength(2)

      // Check specific validation errors
      const firstItemErrors = result.invalid[0].errors
      expect(firstItemErrors).toContain('Name must be at least 2 characters')
      expect(firstItemErrors).toContain('Weight must be greater than 0')

      const secondItemErrors = result.invalid[1].errors
      expect(secondItemErrors).toContain('Weight seems unusually high (>50kg)')
      expect(secondItemErrors).toContain('Quantity must be at least 1')
      expect(secondItemErrors).toContain('Price cannot be negative')
    })

    it('should handle edge cases', () => {
      const items = [
        {
          name: 'Valid Item',
          weight_grams: 100,
          category: 'Other',
          quantity: 1,
          worn: false,
          consumable: false,
          price: 0 // Zero price should be valid
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(1)
      expect(result.invalid).toHaveLength(0)
    })
  })
})

import { useState, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Label } from '@/components/ui/label'
import { Upload, FileText, AlertCircle, Info } from 'lucide-react'
import { parseCsv, validateGearItems } from '@/utils/csvParser'
import type { ParsedGearItem } from '@/utils/csvParser'

interface CsvImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[]) => void
}

export function CsvImport({ onImportData }: CsvImportProps) {
  const [isDragOver, setIsDragOver] = useState(false)
  const [isProcessing, setIsProcessing] = useState(false)
  const [fileName, setFileName] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = (file: File) => {
    if (!file.name.toLowerCase().endsWith('.csv')) {
      onImportData([], ['Please select a CSV file (.csv extension)'])
      return
    }

    setFileName(file.name)
    setIsProcessing(true)

    const reader = new FileReader()
    reader.onload = (e) => {
      const csvContent = e.target?.result as string
      processCsvContent(csvContent)
    }
    reader.onerror = () => {
      onImportData([], ['Failed to read file. Please try again.'])
      setIsProcessing(false)
    }
    reader.readAsText(file)
  }

  const processCsvContent = (csvContent: string) => {
    try {
      // Parse CSV
      const parseResult = parseCsv(csvContent)

      if (!parseResult.success) {
        onImportData([], parseResult.errors, parseResult.warnings)
        setIsProcessing(false)
        return
      }

      // Validate items
      const { valid, invalid } = validateGearItems(parseResult.data)

      const errors: string[] = [...parseResult.errors]
      const warnings: string[] = [...parseResult.warnings]

      // Add validation errors
      invalid.forEach(({ item, errors: itemErrors }) => {
        errors.push(`"${item.name}": ${itemErrors.join(', ')}`)
      })

      // Add warnings for any issues
      if (invalid.length > 0) {
        warnings.push(`${invalid.length} items had validation errors and were skipped`)
      }

      if (valid.length > 0) {
        warnings.push(`Successfully parsed ${valid.length} valid items`)
      }

      onImportData(valid, errors, warnings)

    } catch (error) {
      onImportData([], [`Unexpected error: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)

    const files = Array.from(e.dataTransfer.files)
    if (files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleClickUpload = () => {
    fileInputRef.current?.click()
  }

  return (
    <div className=\"space-y-4\">
      {/* Instructions */}
      <Alert>
        <Info className=\"h-4 w-4\" />
        <AlertDescription>
          <div className=\"font-medium mb-2\">How to export from LighterPack:</div>
          <ol className=\"list-decimal list-inside space-y-1 text-sm\">
            <li>Go to your LighterPack list</li>
            <li>Click the \"Export\" button</li>
            <li>Select \"CSV\" format</li>
            <li>Upload the downloaded file below</li>
          </ol>
        </AlertDescription>
      </Alert>

      {/* File Upload Area */}
      <div
        className={`
          border-2 border-dashed rounded-lg p-8 text-center transition-colors
          ${isDragOver ? 'border-primary bg-primary/5' : 'border-muted-foreground/25'}
          ${isProcessing ? 'opacity-50 pointer-events-none' : 'cursor-pointer hover:border-primary hover:bg-primary/5'}
        `}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClickUpload}
      >
        <input
          ref={fileInputRef}
          type=\"file\"
          accept=\".csv\"
          onChange={handleFileInputChange}
          className=\"hidden\"
          disabled={isProcessing}
        />

        <div className=\"space-y-3\">
          {isProcessing ? (
            <>
              <div className=\"animate-spin rounded-full h-10 w-10 border-b-2 border-primary mx-auto\" />
              <div className=\"text-sm font-medium\">Processing {fileName}...</div>
            </>
          ) : (
            <>
              <Upload className=\"h-10 w-10 text-muted-foreground mx-auto\" />
              <div>
                <div className=\"font-medium\">Drop your CSV file here</div>
                <div className=\"text-sm text-muted-foreground mt-1\">
                  or click to browse files
                </div>
              </div>
              <div className=\"text-xs text-muted-foreground\">
                Supports LighterPack CSV exports (.csv files up to 10MB)
              </div>
            </>
          )}
        </div>
      </div>

      {/* Manual Upload Button */}
      <div className=\"text-center\">
        <Button
          variant=\"outline\"
          onClick={handleClickUpload}
          disabled={isProcessing}
          className=\"w-full sm:w-auto\"
        >
          <FileText className=\"h-4 w-4 mr-2\" />
          Choose CSV File
        </Button>
      </div>

      {/* CSV Format Info */}
      <Alert>
        <Info className=\"h-4 w-4\" />
        <AlertDescription>
          <div className=\"font-medium mb-2\">Expected CSV format:</div>
          <div className=\"text-sm space-y-1\">
            <div><strong>Required columns:</strong> Name, Weight</div>
            <div><strong>Optional columns:</strong> Brand, Category, Quantity, Worn, Consumable, Price, Description, Notes</div>
            <div className=\"text-muted-foreground\">Column names are flexible - we'll automatically detect common variations.</div>
          </div>
        </AlertDescription>
      </Alert>
    </div>
  )
}

