import { describe, it, expect, vi } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { ImportGearForm } from './ImportGearForm'

// Mock the import components
vi.mock('./CsvImport', () => ({
  CsvImport: ({ onImportData }: any) => (
    <div data-testid="csv-import">
      <button onClick={() => onImportData([{ name: 'Test Item', weight_grams: 100, category: 'Test', quantity: 1, worn: false, consumable: false }])}>
        Mock CSV Import
      </button>
    </div>
  )
}))

vi.mock('./UrlImport', () => ({
  UrlImport: ({ onImportData }: any) => (
    <div data-testid="url-import">
      <button onClick={() => onImportData([{ name: 'URL Item', weight_grams: 200, category: 'Test', quantity: 1, worn: false, consumable: false }])}>
        Mock URL Import
      </button>
    </div>
  )
}))

vi.mock('./ImportPreview', () => ({
  ImportPreview: ({ items, onConfirm, onCancel }: any) => (
    <div data-testid="import-preview">
      <div>Previewing {items.length} items</div>
      <button onClick={() => onConfirm(items)}>Confirm Import</button>
      <button onClick={onCancel}>Cancel</button>
    </div>
  )
}))

vi.mock('./ImportResults', () => ({
  ImportResults: ({ state, importedCount, onClose }: any) => (
    <div data-testid="import-results">
      <div>State: {state}</div>
      <div>Imported: {importedCount}</div>
      <button onClick={onClose}>Close</button>
    </div>
  )
}))

describe('ImportGearForm', () => {
  const mockOnClose = vi.fn()
  const mockOnImportComplete = vi.fn()

  it('should render with CSV tab by default', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    expect(screen.getByText('CSV File')).toBeInTheDocument()
    expect(screen.getByText('LighterPack URL')).toBeInTheDocument()
    expect(screen.getByTestId('csv-import')).toBeInTheDocument()
  })

  it('should switch between tabs correctly', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Click URL tab
    fireEvent.click(screen.getByText('LighterPack URL'))
    expect(screen.getByTestId('url-import')).toBeInTheDocument()

    // Click back to CSV tab
    fireEvent.click(screen.getByText('CSV File'))
    expect(screen.getByTestId('csv-import')).toBeInTheDocument()
  })

  it('should handle CSV import flow', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger CSV import
    fireEvent.click(screen.getByText('Mock CSV Import'))

    // Should show preview
    expect(screen.getByTestId('import-preview')).toBeInTheDocument()
    expect(screen.getByText('Previewing 1 items')).toBeInTheDocument()
  })

  it('should handle URL import flow', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Switch to URL tab
    fireEvent.click(screen.getByText('LighterPack URL'))

    // Trigger URL import
    fireEvent.click(screen.getByText('Mock URL Import'))

    // Should show preview
    expect(screen.getByTestId('import-preview')).toBeInTheDocument()
    expect(screen.getByText('Previewing 1 items')).toBeInTheDocument()
  })

  it('should handle preview confirmation', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import and confirm
    fireEvent.click(screen.getByText('Mock CSV Import'))
    fireEvent.click(screen.getByText('Confirm Import'))

    // Should show results
    expect(screen.getByTestId('import-results')).toBeInTheDocument()
    expect(screen.getByText('State: importing')).toBeInTheDocument()
  })

  it('should handle preview cancellation', () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import and cancel
    fireEvent.click(screen.getByText('Mock CSV Import'))
