      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(0)
    })

    it('should consider case-insensitive name matching', () => {
      const items = [
        {
          name: 'Tent',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'TENT', // Same name, different case
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle brand matching for duplicates', () => {
      const items = [
        {
          name: 'Tent',
          brand: 'Zpacks',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Tent',
          brand: 'MSR', // Different brand
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Tent',
          brand: 'Zpacks', // Same brand - should be duplicate
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2) // Zpacks and MSR tents
      expect(result.duplicates).toHaveLength(1) // Second Zpacks tent
    })

    it('should handle items without brands', () => {
      const items = [
        {
          name: 'Water Bottle',
          weight_grams: 150,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Water Bottle', // No brand on either - should be duplicate
          weight_grams: 150,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle multiple duplicates correctly', () => {
      const items = [
        {
          name: 'Energy Bar',
          weight_grams: 50,
          category: 'Food',
          quantity: 1,
          worn: false,
          consumable: true
        },
