import { forwardRef, useContext, createContext } from 'react'

interface TabsContextType {
  value: string
  onValueChange: (value: string) => void
}

const TabsContext = createContext<TabsContextType | undefined>(undefined)

interface TabsProps {
  value: string
  onValueChange: (value: string) => void
  children: React.ReactNode
  className?: string
}

export const Tabs = forwardRef<HTMLDivElement, TabsProps>(({ value, onValueChange, children, className }, ref) => (
  <TabsContext.Provider value={{ value, onValueChange }}>
    <div ref={ref} className={className}>
      {children}
    </div>
  </TabsContext.Provider>
))

interface TabsListProps {
  children: React.ReactNode
  className?: string
}

export const TabsList = forwardRef<HTMLDivElement, TabsListProps>(({ children, className }, ref) => {
  return (
    <div
      ref={ref}
      role="tablist"
      className={`inline-flex h-9 items-center justify-center rounded-lg bg-muted p-1 text-muted-foreground ${className || ''}`}
    >
      {children}
    </div>
  )
})

interface TabsTriggerProps {
  value: string
  children: React.ReactNode
  className?: string
}

export const TabsTrigger = forwardRef<HTMLButtonElement, TabsTriggerProps>(({ value, children, className }, ref) => {
  const context = useContext(TabsContext)
  if (!context) throw new Error('TabsTrigger must be used within Tabs')

  const isActive = context.value === value

  return (
    <button
      ref={ref}
      type="button"
      role="tab"
      aria-selected={isActive}
      className={`inline-flex items-center justify-center whitespace-nowrap rounded-md px-3 py-1 text-sm font-medium ring-offset-background transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 ${
        isActive
          ? 'bg-background text-foreground shadow'
          : 'hover:bg-accent hover:text-accent-foreground'
      } ${className || ''}`}
      onClick={() => context.onValueChange(value)}
    >
      {children}
    </button>
  )
})

interface TabsContentProps {
  value: string
  children: React.ReactNode
  className?: string
}

export const TabsContent = forwardRef<HTMLDivElement, TabsContentProps>(({ value, children, className }, ref) => {
  const context = useContext(TabsContext)
  if (!context) throw new Error('TabsContent must be used within Tabs')

  if (context.value !== value) return null

  return (
    <div
      ref={ref}
      role="tabpanel"
      className={`ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ${className || ''}`}
    >
      {children}
    </div>
  )
})

