#!/usr/bin/env node
import { readFileSync } from 'fs'
import { join } from 'path'
import { parseCsv, validateGearItems, checkForDuplicates } from '../src/utils/csvParser'

// ANSI color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  red: '\x1b[31m',
  cyan: '\x1b[36m'
}

function log(message: string, color?: keyof typeof colors) {
  if (color) {
    console.log(colors[color] + message + colors.reset)
  } else {
    console.log(message)
  }
}

function testCsvFile(filepath: string, filename: string) {
  log(`\n${colors.bright}========================================${colors.reset}`)
  log(`Testing: ${filename}`, 'cyan')
  log(`${colors.bright}========================================${colors.reset}`)

  try {
    const csvContent = readFileSync(filepath, 'utf-8')

    // Parse CSV
    const parseResult = parseCsv(csvContent)

    if (parseResult.success) {
      log(`✓ Successfully parsed CSV`, 'green')
      log(`  - Items found: ${parseResult.data.length}`)
    } else {
      log(`✗ Failed to parse CSV`, 'red')
      parseResult.errors.forEach(error => log(`  Error: ${error}`, 'red'))
      return
    }

    // Show warnings
    if (parseResult.warnings.length > 0) {
      log(`\nWarnings:`, 'yellow')
      parseResult.warnings.forEach(warning => log(`  ⚠ ${warning}`, 'yellow'))
    }

    // Validate items
    const validation = validateGearItems(parseResult.data)
    log(`\nValidation:`, 'blue')
    log(`  - Valid items: ${validation.valid.length}`)
    log(`  - Invalid items: ${validation.invalid.length}`)

    if (validation.invalid.length > 0) {
      log(`\nInvalid items:`, 'red')
      validation.invalid.slice(0, 3).forEach(({ item, errors }) => {
        log(`  - ${item.name}: ${errors.join(', ')}`, 'red')
      })
      if (validation.invalid.length > 3) {
        log(`  ... and ${validation.invalid.length - 3} more`, 'red')
      }
    }

    // Check for duplicates
    const duplicateCheck = checkForDuplicates(validation.valid)
    log(`\nDuplicate check:`, 'blue')
    log(`  - Unique items: ${duplicateCheck.unique.length}`)
    log(`  - Duplicates found: ${duplicateCheck.duplicates.length}`)

    if (duplicateCheck.duplicates.length > 0) {
      log(`\nDuplicate items:`, 'yellow')
      duplicateCheck.duplicates.slice(0, 3).forEach(({ item }) => {
        log(`  - ${item.name} (${item.weight_grams}g)`, 'yellow')
      })
      if (duplicateCheck.duplicates.length > 3) {
        log(`  ... and ${duplicateCheck.duplicates.length - 3} more`, 'yellow')
      }
    }

    // Statistics
    log(`\nStatistics:`, 'blue')

    // Category breakdown
    const categories = new Map<string, number>()
    duplicateCheck.unique.forEach(item => {
      categories.set(item.category, (categories.get(item.category) || 0) + 1)
    })
    log(`  Categories (${categories.size} unique):`)
    Array.from(categories.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .forEach(([cat, count]) => {
        log(`    - ${cat}: ${count} items`)
      })

    // Weight analysis
    const totalWeight = duplicateCheck.unique.reduce(
      (sum, item) => sum + item.weight_grams * item.quantity, 0
    )
    const wornWeight = duplicateCheck.unique
      .filter(item => item.worn)
      .reduce((sum, item) => sum + item.weight_grams * item.quantity, 0)
    const baseWeight = totalWeight - wornWeight

    log(`  Weight breakdown:`)
    log(`    - Total weight: ${(totalWeight / 1000).toFixed(2)}kg (${(totalWeight * 0.035274).toFixed(2)}oz)`)
    log(`    - Worn weight: ${(wornWeight / 1000).toFixed(2)}kg (${(wornWeight * 0.035274).toFixed(2)}oz)`)
    log(`    - Base weight: ${(baseWeight / 1000).toFixed(2)}kg (${(baseWeight * 0.035274).toFixed(2)}oz)`)

    // Brand analysis
    const brands = new Map<string, number>()
    duplicateCheck.unique.forEach(item => {
      if (item.brand) {
        brands.set(item.brand, (brands.get(item.brand) || 0) + 1)
      }
    })
    if (brands.size > 0) {
      log(`  Brands (${brands.size} unique):`)
      Array.from(brands.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .forEach(([brand, count]) => {
          log(`    - ${brand}: ${count} items`)
        })
    }

    // Sample items
    log(`\nSample items:`, 'green')
    duplicateCheck.unique.slice(0, 3).forEach(item => {
      log(`  - ${item.name}${item.brand ? ` (${item.brand})` : ''}`)
      log(`    ${item.category} | ${item.weight_grams}g | Qty: ${item.quantity}${item.worn ? ' | WORN' : ''}`)
    })

  } catch (error) {
    log(`✗ Error processing file: ${error}`, 'red')
  }
}

// Main execution
const examplesPath = join(process.cwd(), 'tests/examples/lighterpack/csv')
const files = [
  'trail-running.csv',
  'four-pass-loop.csv', 
  'jmt-loadout.csv'
]

log(`${colors.bright}${colors.cyan}LighterPack CSV Import Tester${colors.reset}`)
log(`Testing ${files.length} example files from LighterPack exports\n`)

files.forEach(filename => {
  const filepath = join(examplesPath, filename)
  testCsvFile(filepath, filename)
})

log(`\n${colors.bright}${colors.green}All tests complete!${colors.reset}`)
log(`\nThese CSV files are ready to be imported into BetterPack.`)
log(`The import feature will:`)
log(`  • Preserve all item data including weights and quantities`)
log(`  • Extract brands from descriptions`)
log(`  • Keep original categories (including emojis)`)
log(`  • Handle worn/consumable flags`)
log(`  • Detect and handle duplicates`)

